@page "/settings"
@using sv_be93cbd89bf94de8be7df41a0556dc87.Components.Services
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <div class="mb-3">
            <label class="form-label">Theme Mode</label>
            <select class="form-select" @bind="CurrentTheme">
                @foreach (var mode in Enum.GetValues<ThemeMode>())
                {
                    <option value="@mode">@mode</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <input type="color" class="form-control form-control-color"
                   value="@ThemeService.AccentColor"
                   @onchange="OnAccentChanged" />
            <small class="text-muted">@ThemeService.AccentColor</small>
        </div>

        <div class="alert alert-info mb-0">
            Current: <strong>@ThemeService.Theme</strong> &mdash;
            Accent: <span style="color: @ThemeService.AccentColor;">&#9632;</span>
            @ThemeService.AccentColor
        </div>
    </div>
</div>

@code {
    private ThemeMode CurrentTheme
    {
        get => ThemeService.Theme;
        set => ThemeService.Theme = value;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

